<?php
namespace App\Security\Voter;
use App\Entity\Groupe;use App\Entity\User;use App\Repository\GroupeMemberRepository;use Symfony\Component\Security\Core\Authentication\Token\TokenInterface;use Symfony\Component\Security\Core\Authorization\Voter\Voter;
final class GroupeVoter extends Voter{public const VIEW='FACTION_VIEW';public const EDIT='FACTION_EDIT';public const ARCHIVE='FACTION_ARCHIVE';public const JOIN='FACTION_JOIN';public const MANAGE_MEMBERS='FACTION_MANAGE_MEMBERS';public const MANAGE_REQUESTS='FACTION_MANAGE_REQUESTS';public const TRANSFER_OWNERSHIP='FACTION_TRANSFER_OWNERSHIP';public const ACCESS_CHAT='FACTION_ACCESS_CHAT';public const MODERATE_CHAT='FACTION_MODERATE_CHAT';private const ATTRIBUTES=[self::VIEW,self::EDIT,self::ARCHIVE,self::JOIN,self::MANAGE_MEMBERS,self::MANAGE_REQUESTS,self::TRANSFER_OWNERSHIP,self::ACCESS_CHAT,self::MODERATE_CHAT];public function __construct(private readonly GroupeMemberRepository $members){}protected function supports(string $attribute,mixed $subject):bool{return in_array($attribute,self::ATTRIBUTES,true)&&$subject instanceof Groupe;}protected function voteOnAttribute(string $attribute,mixed $subject,TokenInterface $token,?\Symfony\Component\Security\Core\Authorization\Voter\Vote $vote=null):bool{$u=$token->getUser();$g=$subject;if(!$u instanceof User)return $attribute===self::VIEW&&$g->isActive()&&$g->getVisibility()===Groupe::VISIBILITY_PUBLIC;if(in_array($u->getRole(),['ADMIN','MODERATOR'],true))return true;if(!$g->isActive())return false;$m=$this->members->findActive($g,$u);if($attribute===self::VIEW)return $g->getVisibility()===Groupe::VISIBILITY_PUBLIC||$m!==null;if($attribute===self::JOIN)return $m===null;if($m===null)return false;return match($attribute){self::EDIT,self::ARCHIVE,self::TRANSFER_OWNERSHIP=>$m->isOwner(),self::MANAGE_MEMBERS,self::MANAGE_REQUESTS,self::MODERATE_CHAT=>$m->isAdmin(),self::ACCESS_CHAT=>true,default=>false};}}
